import { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { recipeApi, searchApi, rankingApi, bookmarkApi } from '../api';
import { useAuth } from '../context/AuthContext';

export default function RecipeListPage() {
  const { user } = useAuth();
  const [recipes, setRecipes] = useState([]);
  const [ranking, setRanking] = useState([]);
  const [bookmarks, setBookmarks] = useState([]);
  const [keyword, setKeyword] = useState('');
  const [search, setSearch] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [loading, setLoading] = useState(true);
  const debounceRef = useRef(null);

  useEffect(() => {
    setLoading(true);
    recipeApi.getList({ keyword: search || undefined, size: 6 })
      .then(res => setRecipes(res.data.content))
      .catch(console.error)
      .finally(() => setLoading(false));
    rankingApi.getTop().then(res => setRanking(res.data.slice(0, 6))).catch(() => {});
    bookmarkApi.getMy().then(res => setBookmarks(res.data.slice(0, 6))).catch(() => {});
  }, [search]);

  const handleKeywordChange = (e) => {
    const val = e.target.value;
    setKeyword(val);
    clearTimeout(debounceRef.current);
    if (val.trim().length < 1) { setSuggestions([]); return; }
    debounceRef.current = setTimeout(async () => {
      try {
        const res = await searchApi.autocomplete(val.trim());
        setSuggestions(res.data);
      } catch { setSuggestions([]); }
    }, 200);
  };

  const handleSuggestionClick = (s) => {
    setKeyword(s);
    setSuggestions([]);
    setSearch(s);
  };

  return (
    <div>
      {/* 히어로 섹션 */}
      <div style={{ background: '#EEEEEE', padding: '20px 16px 20px', position: 'relative', overflow: 'hidden', borderRadius: '0 0 20px 20px' }}>
        <div style={{ position: 'absolute', top: 0, right: 0, fontSize: 48, opacity: 0.15, lineHeight: 1, padding: 4 }}>
          🍅🌶️🧅🥩🍳
        </div>
        <p style={{ fontSize: 20, fontWeight: 700, margin: '0 0 2px', color: '#111', position: 'relative' }}>
          👋 안녕하세요, {user?.username}님!
        </p>
        <p style={{ fontSize: 13, color: '#555', margin: '0 0 16px', position: 'relative' }}>
          오늘도 맛있는 레시피를 찾아볼까요?
        </p>
        {/* 검색창 */}
        <div style={{ position: 'relative', display: 'flex', gap: 8 }}>
          <div style={{ flex: 1, position: 'relative' }}>
            <input
              style={{ width: '100%', padding: '10px 14px', border: 'none', borderRadius: 8, fontSize: 14, boxSizing: 'border-box', background: '#fff', color: '#333' }}
              placeholder="🔍  레시피 검색... (자동완성 지원)"
              value={keyword}
              onChange={handleKeywordChange}
              onKeyDown={e => { if (e.key === 'Enter') { setSearch(keyword); setSuggestions([]); } }}
              onBlur={() => setTimeout(() => setSuggestions([]), 150)}
            />
            {suggestions.length > 0 && (
              <ul style={suggestStyle}>
                {suggestions.map((s, i) => (
                  <li key={i} style={suggestItem} onMouseDown={() => handleSuggestionClick(s)}>
                    🔍 {s}
                  </li>
                ))}
              </ul>
            )}
          </div>
          <button onClick={() => { setSearch(keyword); setSuggestions([]); }}
            style={{ padding: '10px 20px', background: '#111', color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer', fontSize: 14 }}>
            검색
          </button>
        </div>
      </div>

      <div style={{ padding: '24px 16px' }}>
        {/* 전체 레시피 */}
        <Section title="🍽️ 전체 레시피" linkTo={null}>
          {loading ? (
            <p style={{ color: '#888', fontSize: 13 }}>불러오는 중...</p>
          ) : recipes.length === 0 ? (
            <p style={{ color: '#888', fontSize: 13 }}>등록된 레시피가 없습니다.</p>
          ) : (
            <div style={grid}>
              {recipes.map(r => <RecipeCard key={r.id} recipe={r} />)}
            </div>
          )}
        </Section>

        {/* 즐겨찾는 레시피 */}
        <Section title="⭐ 즐겨찾는 레시피" linkTo="/my-recipes">
          {bookmarks.length === 0 ? (
            <p style={{ color: '#888', fontSize: 13 }}>즐겨찾기한 레시피가 없습니다.</p>
          ) : (
            <div style={grid}>
              {bookmarks.map(r => <RecipeCard key={r.id} recipe={r} />)}
            </div>
          )}
        </Section>

        {/* 인기 랭킹 */}
        <Section title="🔥 인기 랭킹" linkTo={null}>
          {ranking.length === 0 ? (
            <p style={{ color: '#888', fontSize: 13 }}>아직 조회 데이터가 없습니다.</p>
          ) : (
            <div style={grid}>
              {ranking.map((r, idx) => <RecipeCard key={r.id} recipe={r} rank={idx + 1} />)}
            </div>
          )}
        </Section>
      </div>
    </div>
  );
}

function Section({ title, linkTo, children }) {
  return (
    <div style={{ marginBottom: 36 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
        <h2 style={{ margin: 0, fontSize: 17, fontWeight: 700 }}>{title}</h2>
        {linkTo && (
          <Link to={linkTo} style={{ fontSize: 13, color: '#888', textDecoration: 'none' }}>전체보기 →</Link>
        )}
      </div>
      {children}
    </div>
  );
}

function RecipeCard({ recipe, rank }) {
  return (
    <Link to={`/recipes/${recipe.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>
      <div style={cardStyle}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
          <h3 style={{ margin: 0, fontSize: 15, fontWeight: 600, flex: 1, marginRight: 8 }}>{recipe.title}</h3>
          <div style={{ display: 'flex', gap: 4, flexShrink: 0 }}>
            {rank && (
              <span style={{ ...badge, background: rank <= 3 ? '#111' : '#888', color: '#fff' }}>
                {rank === 1 ? '🥇' : rank === 2 ? '🥈' : rank === 3 ? '🥉' : `#${rank}`}
              </span>
            )}
            {recipe.forkedFromId && <span style={{ ...badge, background: '#555', color: '#fff' }}>Fork</span>}
          </div>
        </div>
        <p style={{ color: '#777', fontSize: 12, margin: '6px 0 10px' }}>
          {recipe.description?.slice(0, 50) || '설명 없음'}
        </p>
        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
          <span style={badge}>{recipe.category}</span>
          {recipe.difficulty && <span style={badge}>{recipe.difficulty}</span>}
          {recipe.cookingTime && <span style={badge}>{recipe.cookingTime}분</span>}
        </div>
        <p style={{ fontSize: 11, color: '#aaa', marginTop: 8, marginBottom: 0 }}>by {recipe.ownerUsername}</p>
      </div>
    </Link>
  );
}

